<?php
require_once __DIR__ . '/../../app/auth.php';
require_once __DIR__ . '/../../app/view.php';
require_once __DIR__ . '/../../app/settings.php';
require_once __DIR__ . '/../../app/activity.php';
$db = database(); $user = admin_user($db); $companyId = (int)$user['company_id'];
$settings = workspace_settings($db,$companyId); $currency = (string)($settings['currency'] ?? '');
$count = fn(string $sql, array $params = []) => (int)db_one($db,$sql,[$companyId,...$params])['count'];
$counts = [];
foreach (['projects','tasks','employees','managers','customers','departments'] as $table) $counts[$table] = $count("SELECT COUNT(*) AS count FROM `$table` WHERE company_id = ?");
$today = date('Y-m-d');
$taskStatus = ['pending'=>0,'ongoing'=>0,'completed'=>0];
foreach (db_rows($db,'SELECT status, COUNT(*) AS count FROM tasks WHERE company_id = ? GROUP BY status',[$companyId]) as $row) if (isset($taskStatus[$row['status']])) $taskStatus[$row['status']] = (int)$row['count'];
$openTasks = $taskStatus['pending'] + $taskStatus['ongoing'];
$overdue = $count("SELECT COUNT(*) AS count FROM tasks WHERE company_id = ? AND status != 'completed' AND due_date < ?",[$today]);
$activeProjects = $count("SELECT COUNT(*) AS count FROM projects WHERE company_id = ? AND status IN ('ongoing','pending')");
$pipeline = db_one($db,"SELECT COUNT(*) AS count, COALESCE(SUM(amount),0) AS total FROM deals WHERE company_id = ? AND stage IN ('proposal','negotiation')",[$companyId]);
$stages = [];
foreach (db_rows($db,'SELECT stage, COUNT(*) AS count, COALESCE(SUM(amount),0) AS total FROM deals WHERE company_id = ? GROUP BY stage',[$companyId]) as $row) $stages[$row['stage']] = $row;
$monthStart = date('Y-m-01'); $monthEnd = date('Y-m-t');
$ledger = db_one($db,"SELECT COALESCE(SUM(CASE WHEN type = 'income' THEN amount END),0) AS income, COALESCE(SUM(CASE WHEN type = 'expense' THEN amount END),0) AS spent FROM ledger_entries WHERE company_id = ? AND date BETWEEN ? AND ?",[$companyId,$monthStart,$monthEnd]);
$expenses = (float)db_one($db,'SELECT COALESCE(SUM(amount),0) AS total FROM expenses WHERE company_id = ? AND date BETWEEN ? AND ?',[$companyId,$monthStart,$monthEnd])['total'];
$income = (float)$ledger['income']; $spent = (float)$ledger['spent'] + $expenses;
$unpaid = db_one($db,"SELECT COUNT(*) AS count, COALESCE(SUM(amount),0) AS total, COALESCE(SUM(due_date < ?),0) AS overdue FROM invoices WHERE company_id = ? AND status = 'Unpaid'",[$today,$companyId]);
$focus = db_rows($db,"SELECT t.id, t.title, t.due_date, t.priority, t.status, p.projectName FROM tasks t LEFT JOIN projects p ON " . task_project_join() . " WHERE t.company_id = ? AND t.status != 'completed' ORDER BY t.due_date IS NULL, t.due_date, t.id LIMIT 6",[$companyId]);
$projects = db_rows($db,"SELECT id, projectName, status, endDate FROM projects WHERE company_id = ? AND status != 'completed' ORDER BY endDate IS NULL, endDate, id DESC LIMIT 4",[$companyId]);
$progress = project_task_progress($db,$companyId);
$upcoming = [];
foreach (db_rows($db,'SELECT event_id, event_name, start_datetime, end_datetime, timezone, event_type, meetup_venue FROM events WHERE company_id = ? AND event_date BETWEEN ? AND ? ORDER BY event_date, start_datetime LIMIT 40',[$companyId,date('Y-m-d',strtotime('-1 day')),date('Y-m-d',strtotime('+30 days'))]) as $event) {
    try { $zone = new DateTimeZone($event['timezone'] ?: 'UTC'); $start = new DateTimeImmutable($event['start_datetime'],$zone); $end = new DateTimeImmutable($event['end_datetime'] ?: $event['start_datetime'],$zone); } catch (Exception) { continue; }
    if ($end->getTimestamp() < time()) continue;
    $upcoming[] = $event + ['start'=>$start,'live'=>$start->getTimestamp() <= time()];
    if (count($upcoming) === 4) break;
}
$hiring = db_one($db,"SELECT (SELECT COUNT(*) FROM job_posts WHERE company_id = ? AND status = 'published') AS jobs, (SELECT COUNT(*) FROM applications WHERE company_id = ? AND status IN ('new','reviewing')) AS reviewing",[$companyId,$companyId]);
$activity = activity_entries($db,$companyId,activity_rows($db,$companyId,6),(int)$user['id']);
$invited = $count('SELECT COUNT(*) AS count FROM staff_invitations WHERE company_id = ?');
$steps = [
    ['Verify your email',true,'/users/admin/settings.php'],
    ['Set your currency and timezone',$currency !== '','/users/admin/settings.php'],
    ['Create a department',$counts['departments']>0,'/users/admin/workspace.php?module=departments&action=new'],
    ['Add your team',$counts['employees']>0,'/users/admin/workspace.php?module=employees&action=new'],
    ['Invite a teammate to sign in',$invited>0,'/users/admin/workspace.php?module=employees'],
    ['Start your first project',$counts['projects']>0,'/users/admin/workspace.php?module=projects&action=new'],
];
$done = count(array_filter($steps,fn($step)=>$step[1]));
$compact = function (float $amount) use ($currency): string {
    $sign = $amount < 0 ? '−' : ''; $amount = abs($amount);
    $text = match (true) { $amount >= 1e9 => round($amount/1e9,1) . 'B', $amount >= 1e6 => round($amount/1e6,1) . 'M', $amount >= 1e4 => round($amount/1e3,1) . 'K', default => number_format($amount,0) };
    return $sign . ($currency !== '' ? $currency . ' ' : '') . $text;
};
$hour = (int)date('G');
$greeting = $hour < 12 ? 'Good morning' : ($hour < 17 ? 'Good afternoon' : 'Good evening');
$dueLabel = function (?string $date) use ($today): array {
    if (!$date) return ['No due date',''];
    $days = (int)round((strtotime($date) - strtotime($today)) / 86400);
    return match (true) { $days < 0 => [abs($days) === 1 ? 'Overdue by 1 day' : 'Overdue by ' . abs($days) . ' days','overdue'], $days === 0 => ['Due today','soon'], $days === 1 => ['Due tomorrow','soon'], $days < 7 => ['Due in ' . $days . ' days',''], default => ['Due ' . date('j M',strtotime($date)),''] };
};
suite_start('Overview','overview',$user);
?>
<div class="page-heading dashboard-heading"><div><span class="greeting"><?= e($greeting) ?> · <?= e(date('l, j F')) ?></span><h1>Business overview</h1><p>Here’s what’s moving at <?= e($user['company_name']) ?> today.</p></div><div class="heading-actions"><button type="button" class="button secondary small" data-command-open><?= icon('search') ?> Search</button><a class="button small" href="/users/admin/workspace.php?module=tasks&amp;action=new"><?= icon('plus') ?> Create task</a></div></div>
<?php if ($overdue > 0 || (int)$unpaid['overdue'] > 0): ?><div class="attention-strip" role="status"><?= icon('alert') ?><span><?php $parts = []; if ($overdue > 0) $parts[] = '<a href="/users/admin/workspace.php?module=tasks&amp;view=board">' . $overdue . ' overdue ' . ($overdue === 1 ? 'task' : 'tasks') . '</a>'; if ((int)$unpaid['overdue'] > 0) $parts[] = '<a href="/users/admin/workspace.php?module=invoices&amp;stage=Unpaid">' . (int)$unpaid['overdue'] . ' overdue ' . ((int)$unpaid['overdue'] === 1 ? 'invoice' : 'invoices') . '</a>'; echo 'Needs attention: ' . implode(' and ',$parts) . '.'; ?></span></div><?php endif; ?>
<div class="stats-grid kpi-grid">
<a class="stat-card kpi" href="/users/admin/workspace.php?module=projects"><div class="stat-label"><span>Active projects</span><span class="kpi-icon"><?= icon('folder') ?></span></div><div class="stat-value"><?= number_format($activeProjects) ?></div><div class="stat-foot"><?= number_format($counts['projects']) ?> in total</div></a>
<a class="stat-card kpi" href="/users/admin/workspace.php?module=tasks&amp;view=board"><div class="stat-label"><span>Open tasks</span><span class="kpi-icon"><?= icon('task') ?></span></div><div class="stat-value"><?= number_format($openTasks) ?></div><div class="stat-foot"><?php if ($overdue > 0): ?><span class="kpi-flag bad"><?= $overdue ?> overdue</span><?php else: ?><span class="kpi-flag good">Nothing overdue</span><?php endif; ?></div></a>
<a class="stat-card kpi" href="/users/admin/workspace.php?module=deals&amp;view=board"><div class="stat-label"><span>Open pipeline</span><span class="kpi-icon"><?= icon('target') ?></span></div><div class="stat-value"><?= e($compact((float)$pipeline['total'])) ?></div><div class="stat-foot"><?= (int)$pipeline['count'] ?> open <?= (int)$pipeline['count'] === 1 ? 'deal' : 'deals' ?></div></a>
<a class="stat-card kpi" href="/users/admin/workspace.php?module=ledger"><div class="stat-label"><span>Net cash · <?= e(date('F')) ?></span><span class="kpi-icon"><?= icon('wallet') ?></span></div><div class="stat-value<?= $income - $spent < 0 ? ' negative' : '' ?>"><?= e($compact($income - $spent)) ?></div><div class="stat-foot"><?= e($compact($income)) ?> in · <?= e($compact($spent)) ?> out</div></a>
</div>
<div class="dashboard-columns">
<div>
<section class="panel"><div class="panel-head"><h2>Your focus</h2><a class="text-link" href="/users/admin/workspace.php?module=tasks&amp;view=board">Open board <?= icon('arrow') ?></a></div><?php if (!$focus): ?><div class="empty-state"><?= icon('task') ?><h3><?= $counts['tasks'] ? 'All caught up' : 'No tasks yet' ?></h3><p><?= $counts['tasks'] ? 'Every task is complete. Nice work.' : 'Create a task and give it a due date to see it here.' ?></p><a class="button small secondary" href="/users/admin/workspace.php?module=tasks&amp;action=new"><?= icon('plus') ?> Create task</a></div><?php else: ?><ul class="focus-list"><?php foreach ($focus as $task): [$label,$tone] = $dueLabel($task['due_date']); ?><li><span class="focus-check <?= e(stage_class($task['status'])) ?>" aria-hidden="true"></span><div><a href="/users/admin/workspace.php?module=tasks&amp;action=view&amp;id=<?= (int)$task['id'] ?>"><?= e($task['title']) ?></a><small><?= $task['projectName'] ? e($task['projectName']) . ' · ' : '' ?><span class="due <?= e($tone) ?>"><?= e($label) ?></span></small></div><span class="badge <?= e(stage_class($task['priority'])) ?>"><?= e($task['priority']) ?></span></li><?php endforeach; ?></ul><?php endif; ?></section>
<section class="panel"><div class="panel-head"><h2>Projects in motion</h2><a class="text-link" href="/users/admin/workspace.php?module=projects">All projects <?= icon('arrow') ?></a></div><?php if (!$projects): ?><div class="empty-state"><?= icon('folder') ?><h3>No active projects</h3><p>Create a project to organize its team, tasks and milestones.</p><a class="button small secondary" href="/users/admin/workspace.php?module=projects&amp;action=new"><?= icon('plus') ?> Create project</a></div><?php else: ?><ul class="project-list"><?php foreach ($projects as $project): $late = $project['endDate'] && $project['endDate'] < $today; ?><li><span class="record-icon"><?= icon('folder') ?></span><div><a href="/users/admin/workspace.php?module=projects&amp;action=view&amp;id=<?= (int)$project['id'] ?>"><?= e($project['projectName']) ?></a><small class="<?= $late ? 'due overdue' : '' ?>"><?= $project['endDate'] ? ($late ? 'Was due ' : 'Due ') . e(date('j M Y',strtotime($project['endDate']))) : 'No end date' ?></small></div><?= progress_html($progress[(int)$project['id']] ?? null) ?><span class="badge <?= e(stage_class($project['status'])) ?>"><?= e($project['status'] ?: 'planned') ?></span></li><?php endforeach; ?></ul><?php endif; ?></section>
<section class="panel"><div class="panel-head"><h2>Sales pipeline</h2><a class="text-link" href="/users/admin/workspace.php?module=deals&amp;view=board">Deal board <?= icon('arrow') ?></a></div><?php if (!$stages): ?><div class="empty-state"><?= icon('target') ?><h3>No deals yet</h3><p>Track opportunities from proposal to outcome.</p><a class="button small secondary" href="/users/admin/workspace.php?module=deals&amp;action=new"><?= icon('plus') ?> Add deal</a></div><?php else: $max = max(1,max(array_map(fn($row)=>(float)$row['total'],$stages))); ?><div class="panel-body pipeline"><?php foreach (['proposal','negotiation','won','lost'] as $stage): $row = $stages[$stage] ?? ['count'=>0,'total'=>0]; ?><a class="pipeline-row" href="/users/admin/workspace.php?module=deals&amp;stage=<?= e($stage) ?>"><span class="pipeline-label"><i class="stage-dot <?= e($stage) ?>"></i><?= e(ucfirst($stage)) ?> <small><?= (int)$row['count'] ?></small></span><span class="pipeline-bar"><span class="<?= e($stage) ?>" style="width:<?= max(2,(int)round((float)$row['total'] / $max * 100)) ?>%"></span></span><strong><?= e($compact((float)$row['total'])) ?></strong></a><?php endforeach; ?></div><?php endif; ?></section>
</div>
<aside>
<?php if ($done < count($steps)): ?><section class="panel setup-panel"><div class="panel-head"><h2>Get set up</h2><span class="badge"><?= $done ?> of <?= count($steps) ?></span></div><div class="panel-body"><div class="setup-meter"><span style="width:<?= (int)round($done / count($steps) * 100) ?>%"></span></div><ul class="checklist"><?php foreach ($steps as $index=>[$label,$complete,$url]): ?><li class="<?= $complete ? 'done' : '' ?>"><span><?= $complete ? icon('check') : $index+1 ?></span><span><?= e($label) ?></span><?php if (!$complete): ?><a href="<?= e($url) ?>" aria-label="<?= e($label) ?>"><?= icon('arrow') ?></a><?php endif; ?></li><?php endforeach; ?></ul></div></section><?php endif; ?>
<section class="panel"><div class="panel-head"><h2>Task progress</h2><span class="count-label"><?= number_format(array_sum($taskStatus)) ?> tasks</span></div><div class="panel-body donut-wrap"><?php $total = array_sum($taskStatus); $offset = 25; ?><svg class="donut" viewBox="0 0 42 42" role="img" aria-label="<?= $total ? (int)round($taskStatus['completed'] / $total * 100) . '% of tasks complete' : 'No tasks yet' ?>"><circle cx="21" cy="21" r="15.915" fill="none" stroke="#edf1e8" stroke-width="5"/><?php if ($total): foreach (['completed'=>'#5c9a3f','ongoing'=>'#4a82bf','pending'=>'#e0a63a'] as $status=>$colour): $share = $taskStatus[$status] / $total * 100; if ($share <= 0) continue; ?><circle cx="21" cy="21" r="15.915" fill="none" stroke="<?= $colour ?>" stroke-width="5" stroke-dasharray="<?= round($share,2) ?> <?= round(100 - $share,2) ?>" stroke-dashoffset="<?= round($offset,2) ?>"/><?php $offset -= $share; endforeach; endif; ?><text x="21" y="21" text-anchor="middle" class="donut-value"><?= $total ? (int)round($taskStatus['completed'] / $total * 100) . '%' : '—' ?></text><text x="21" y="26.5" text-anchor="middle" class="donut-caption">complete</text></svg><ul class="legend"><?php foreach (['completed'=>'Completed','ongoing'=>'Ongoing','pending'=>'Pending'] as $status=>$label): ?><li><i class="stage-dot <?= $status ?>"></i><a href="/users/admin/workspace.php?module=tasks&amp;view=list&amp;stage=<?= $status ?>"><?= $label ?></a><strong><?= $taskStatus[$status] ?></strong></li><?php endforeach; ?></ul></div></section>
<section class="panel"><div class="panel-head"><h2>Coming up</h2><a class="text-link" href="/users/admin/calendar.php">Calendar <?= icon('arrow') ?></a></div><?php if (!$upcoming): ?><div class="empty-state compact"><?= icon('calendar') ?><h3>Nothing scheduled</h3><p>Plan a meeting or event for your team.</p><a class="button small secondary" href="/users/admin/workspace.php?module=events&amp;action=new"><?= icon('plus') ?> Add event</a></div><?php else: ?><ul class="agenda"><?php foreach ($upcoming as $event): ?><li><span class="agenda-date"><small><?= e($event['start']->format('M')) ?></small><strong><?= e($event['start']->format('j')) ?></strong></span><div><a href="/users/admin/meeting.php?event=<?= (int)$event['event_id'] ?>"><?= e($event['event_name']) ?></a><small><?= $event['live'] ? '<span class="live-dot"></span>Happening now · ' : e($event['start']->format('D, H:i T')) . ' · ' ?><?= $event['event_type'] === 'online' ? 'Online' : e($event['meetup_venue'] ?: 'In person') ?></small></div></li><?php endforeach; ?></ul><?php endif; ?></section>
<section class="panel"><div class="panel-head"><h2>Money</h2><a class="text-link" href="/users/admin/accounting.php" aria-label="Open accounting statements">Statements <?= icon('arrow') ?></a></div><div class="panel-body mini-metrics"><div><span>Received in <?= e(date('F')) ?></span><strong><?= e($compact($income)) ?></strong></div><div><span>Spent in <?= e(date('F')) ?></span><strong><?= e($compact($spent)) ?></strong></div><div><span>Unpaid invoices</span><strong><?= e($compact((float)$unpaid['total'])) ?></strong><small><?= (int)$unpaid['count'] ?> open<?= (int)$unpaid['overdue'] ? ' · ' . (int)$unpaid['overdue'] . ' overdue' : '' ?></small></div><div><span>Hiring</span><strong><?= (int)$hiring['jobs'] ?> open <?= (int)$hiring['jobs'] === 1 ? 'role' : 'roles' ?></strong><small><?= (int)$hiring['reviewing'] ?> to review</small></div><?php if ($currency === ''): ?><p class="subtle mini-note"><a class="text-link" href="/users/admin/settings.php">Set your currency</a> to label amounts.</p><?php endif; ?></div></section>
<section class="panel"><div class="panel-head"><h2>Recent activity</h2><a class="text-link" href="/users/admin/activity.php">View all <?= icon('arrow') ?></a></div><?php if (!$activity): ?><div class="empty-state compact"><?= icon('pulse') ?><h3>No activity yet</h3><p>Changes across your workspace will appear here.</p></div><?php else: ?><ul class="activity-feed compact"><?php foreach ($activity as $entry): ?><li><span class="activity-icon"><?= icon($entry['icon']) ?></span><div><p><?php if ($entry['url']): ?><a href="<?= e($entry['url']) ?>"><?= e($entry['text']) ?></a><?php else: ?><?= e($entry['text']) ?><?php endif; ?></p><time datetime="<?= e($entry['time']) ?>Z" title="<?= e($entry['time']) ?> UTC"><?= e(time_ago($entry['time'])) ?></time></div></li><?php endforeach; ?></ul><?php endif; ?></section>
</aside>
</div>
<?php suite_end(); ?>
